import 'package:flutter/material.dart';
import '../utils/gold_formulas.dart';
import '../widgets/number_input.dart';
import '../widgets/result_card.dart';
class SellCalculatorScreen extends StatefulWidget{const SellCalculatorScreen({super.key});@override State<SellCalculatorScreen> createState()=>_SellCalculatorScreenState();}
class _SellCalculatorScreenState extends State<SellCalculatorScreen>{final price=TextEditingController(),weight=TextEditingController(),karat=TextEditingController(text:'18');double result=0;void calculate(){final p=double.tryParse(price.text)??0,w=double.tryParse(weight.text)??0,k=double.tryParse(karat.text)??18;setState(()=>result=GoldFormulas.rawGoldValue(weight:w,pricePerGram:p*k/18));}@override void dispose(){price.dispose();weight.dispose();karat.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('محاسبه قیمت فروش')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('ارزش تقریبی طلای شما',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:14),NumberInput(controller:price,label:'قیمت هر گرم طلای ۱۸ عیار',suffix:'تومان',decimal:false),const SizedBox(height:12),NumberInput(controller:weight,label:'وزن طلا',suffix:'گرم'),const SizedBox(height:12),NumberInput(controller:karat,label:'عیار',suffix:'عیار',decimal:false),const SizedBox(height:18),FilledButton.icon(onPressed:calculate,icon:const Icon(Icons.sell_rounded),label:const Text('محاسبه ارزش')),if(result>0)...[const SizedBox(height:18),ResultCard(title:'نتیجه تقریبی',children:[ResultRow(title:'ارزش طلا',value:result,bold:true),const SizedBox(height:4),Text('مبلغ نهایی فروش ممکن است با توجه به شرایط معامله متفاوت باشد.',style:TextStyle(fontSize:11.5,color:Colors.grey))])]]));}
